from lib import *
S = SS('q1')
steps = [
    step("经过一个 TCP 代理看连接是怎么建起来的:客户端先发 8 字节的协议头(AMQP 0-9-1),然后 broker 发 Connection.Start(528 字节,里面是产品名、版本和能力表),客户端回 StartOk(328 字节,选认证方式并带上用户名密码),broker 发 Tune、客户端回 TuneOk(协商 heartbeat 和 frame_max),客户端发 Connection.Open 选 vhost,broker 回 OpenOk——一共 7 个帧、4 个来自客户端。全部发生在 0 号通道上,0 号通道专管连接本身。协商结果是 heartbeat = 60 秒、frame_max = 131072。Start 帧里告知的版本是 RabbitMQ 4.3.6,能力里值为 True 的有 publisher_confirms、basic.nack、consumer_cancel_notify、connection.blocked、direct_reply_to 等 9 项。", t=tl(S(1)), mark=lidx(S(1), 'Connection.Start ', 'Connection.Tune ', 'Connection.TuneOk'), done=lidx(S(1), 'ProtocolHeader', 'Connection.Open ', 'Connection.OpenOk', '握手共 7 帧'), kv=KV([['协议头', 'AMQP 0-9-1,8 字节'], ['Start / StartOk', '版本、能力、认证'], ['Tune / TuneOk', 'heartbeat、frame_max、channel_max'], ['Open / OpenOk', '选 vhost'], ['通道号', '0 = 连接本身']], ['Tune / TuneOk'])),
    step("在 1 号通道上依次声明 exchange、队列、绑定,再发布一条 5 字节的消息 b\"hello\",再用 Basic.Get 取回来并 ack。每个操作都是一个“请求帧 + 对应的 Ok 帧”(DeclareOk 12~27 字节)。发布不一样:Basic.Publish(25 字节)后面还跟着 ContentHeader(22 字节,放属性和消息体总长度)和 ContentBody(13 字节,放 5 字节消息体加 8 字节帧开销),一共三个帧;而且发布没有 Ok 回包(没开 confirm 的话)。取回时 broker 回 GetOk + ContentHeader + ContentBody,客户端最后发 Basic.Ack(21 字节)。", t=tl(S(2)), mark=lidx(S(2), 'Basic.Publish', 'ContentHeader', 'ContentBody'), done=lidx(S(2), 'Exchange.Declare ', 'Queue.Declare ', 'Queue.Bind ', 'Basic.Ack'), kv=KV([['请求-应答', 'Declare / Bind 都有 Ok'], ['发布', '方法帧 + 内容头 + 内容体,没有 Ok'], ['内容头', '放属性和 body 总长度'], ['帧开销', '每帧 8 字节(7 字节头 + 1 字节结尾)']], ['发布'])),
    step("同一条 TCP 连接上开 3 个 channel(pika 里编号 1、2、3),rabbitmqctl list_connections 看到的是 1 条连接 channels = 3;list_channels 列出三行,编号 1、2、3。channel 是连接里的逻辑通道,共用一条 TCP 连接,每个 channel 有自己的方法顺序、自己的消费者和确认状态。", t=tl(S(3)), mark=lidx(S(3), 'running\t3', 'running'), done=lidx(S(3), '1\t0\t0', '2\t0\t0', '3\t0\t0', 'pika 里三个'), kv=KV([['连接', '一条 TCP'], ['channel', '连接里的逻辑通道,编号 1、2、3'], ['每个 channel', '自己的消费者、确认、prefetch']], ['channel'])),
    step("错误的“范围”不同:对不存在的队列做 passive declare,broker 回 404 NOT_FOUND 并关掉这个 channel,其余 channel 和连接都不受影响(list_channels 只剩 1、3 号);对没发过的 delivery_tag 做 ack,线上帧是 Basic.Ack → Channel.Close(68 字节,406 PRECONDITION_FAILED unknown delivery tag)→ Channel.CloseOk;声明不存在的 exchange 类型也是 406,连接还开着。连不存在的 vhost(530 NOT_ALLOWED)和用错误的密码(403 ACCESS_REFUSED)则是连接级错误,整条连接都没了。", t=tl(S(4)), mark=lidx(S(4), '404', 'Channel.Close', '406', '530', '403'), done=lidx(S(4), 'channel 1 状态', '连接 is_open=True', '这两种是连接级错误'), kv=KV([['channel 级错误', '404 / 406:只关出错的 channel'], ['连接级错误', '403 / 530:整条连接关闭'], ['线上', 'Channel.Close → Channel.CloseOk'], ['其它 channel', '不受影响']], ['channel 级错误'])),
    step("三种对象在 broker 里的样子:list_exchanges 列出默认的无名 exchange(direct)和 amq.direct、amq.fanout、amq.headers、amq.match、amq.topic、amq.rabbitmq.log、amq.rabbitmq.trace 加上我声明的 x.demo(共 9 个);list_queues 只有 q.demo,消息数 0(上面已经取走并 ack);list_bindings 有两行:我绑定的 x.demo → q.demo(routing key k1),以及每个队列都自动有的、来自默认 exchange 的绑定(routing key 就是队列名 q.demo)。", t=tl(S(5)), mark=lidx(S(5), 'x.demo\tdirect', 'x.demo\texchange', 'exchange\tq.demo\tqueue\tq.demo'), done=lidx(S(5), 'amq.direct', 'q.demo\ttrue\t0'), kv=KV([['默认 exchange', '名字是空串,direct 类型'], ['预置 exchange', 'amq.direct / fanout / topic / headers …'], ['binding', 'exchange → queue 的一条规则'], ['每个队列', '自动绑到默认 exchange,key = 队列名']], ['默认 exchange'])),
    step("开销对比:基线 Erlang 进程 385 个、内存 62.8 MiB。开 100 个连接(各 1 个 channel)后进程 1485(多 1100,即每个连接连同它的 1 个 channel 约 11 个进程),内存 70.0 MiB(多 7.2 MiB,每个约 74 KiB);连接全关后回到 385 个进程。1 个连接开 100 个 channel:进程 792(多 407,每个 channel 约 4 个进程),内存 66.7 MiB(多 2.3 MiB,每个 channel 约 23 KiB)。所以 channel 比连接便宜得多,但也不是免费的。", t=tl(S(6)), mark=lidx(S(6), '100 个连接 × 1 个 channel', '1 个连接 × 100 个 channel'), done=lidx(S(6), '基线', '关掉后回到'), b=bars([['100 连接×1 channel', 1100, '+1100 进程'], ['1 连接×100 channel', 407, '+407 进程']], 1100, mark=[0], done=[1]), kv=KV([['连接 + 1 个 channel', '约 11 个 Erlang 进程,约 74 KiB'], ['channel', '约 4 个进程,约 23 KiB'], ['关掉连接', '进程数回到基线']], ['channel'])),
]
A = mkartq('q1', 1, 'RabbitMQ,AMQP,connection,channel,exchange,queue,binding,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上用 TCP 代理解析 AMQP 0-9-1 的帧:连接握手 7 个帧,发布一条消息是方法帧加内容头加内容体 3 个帧;channel 级错误只关 channel,连接级错误关整条连接;rabbitmqctl 列出预置的 exchange、队列和绑定;100 个连接约 +1100 个 Erlang 进程,而 1 个连接 100 个 channel 只 +407。',
    'connection、channel、exchange、queue、binding 这五个词是 AMQP 的全部家当,但它们各自在网线上长什么样、在 broker 里占什么?这篇用一个 TCP 代理把 AMQP 0-9-1 的帧一帧一帧打出来,再用 rabbitmqctl 和管理 API 看这几类对象在 RabbitMQ 4.3.6 里的真实样子和开销。',
    [('7 帧', '一次 AMQP 连接握手用到的帧数(协议头不算帧),4 个来自客户端'), ('3 帧', '发布一条 5 字节的消息:方法帧 + 内容头 + 内容体'), ('+1100 vs +407', '100 个连接(各 1 个 channel)与 1 个连接 100 个 channel,在 broker 里多出的 Erlang 进程数')],
    [('连接与握手', '<p>一条 AMQP 连接建立在一条 TCP 连接上:客户端先发 8 字节协议头,接着是 <code>Connection.Start / StartOk</code>(版本、能力、认证)、<code>Tune / TuneOk</code>(协商心跳间隔和最大帧长)、<code>Open / OpenOk</code>(选 vhost)。这些帧都走 0 号通道。握手完才有“channel”可言。</p>'),
     ('方法帧、内容头、内容体', '<p>AMQP 的帧有四种:方法(method)、内容头(header)、内容体(body)和心跳。<code>Exchange.Declare</code> 这类操作只有一个方法帧加一个 Ok;发布则是 <code>Basic.Publish</code> + 内容头 + 内容体三个帧,没开 confirm 时不会有回包。每个帧固定 8 字节开销(7 字节头 + 1 字节结尾)。</p>'),
     ('channel', '<p>channel 是连接内的逻辑通道,共用一条 TCP 连接,各有自己的消费者、确认状态和 prefetch。<code>rabbitmqctl list_connections</code> 的 <code>channels</code> 列和 <code>list_channels</code> 能直接看到。</p>'),
     ('错误的范围', '<p>资源或使用错误(404 找不到队列、406 前置条件不满足)只关出错的 channel:broker 发 <code>Channel.Close</code>,客户端回 <code>CloseOk</code>,别的 channel 继续用。认证失败(403)、vhost 不存在(530)这类是连接级错误,整条连接被关闭。</p>'),
     ('exchange、queue、binding', '<p>消息先到 exchange,按 binding 里的规则转到队列。<code>list_exchanges</code> 里有一个名字是空串的默认 exchange 和一组 <code>amq.*</code> 预置 exchange;每个队列都自动以队列名为 routing key 绑在默认 exchange 上,所以“直接发到队列”其实也是走了 exchange。</p>'),
     ('开销', '<p>在 broker 一侧,一个连接(带 1 个 channel)约 11 个 Erlang 进程,每多一个 channel 约多 4 个。连接数多比 channel 数多贵得多——这也是客户端通常用少量连接、多个 channel 的原因(具体多少合适见本系列「连接与 channel 的数量」那一篇)。</p>')],
    steps,
    [ENV_Q + '。第一、二、四节经过自己写的 TCP 代理(按 AMQP 0-9-1 帧格式解析两个方向的字节);第六节的进程数和内存来自 rabbitmqctl eval 调用 erlang:system_info(process_count) 与 erlang:memory(total),每一项只取一次测量',
     '没有验证:TLS 连接与证书认证;AMQP 1.0 和其它协议(MQTT、STOMP)的连接模型;多 vhost、多用户的权限;连接和 channel 数很大(几万)时的行为;channel_max 的上限与超过时的错误;不同版本 RabbitMQ 或 Erlang 的开销数字'],
    'AMQP 模型')
